const WHITELIST = []; // [] = responde a todos os contatos diretos (modo produção)
const EVOLUTION = 'http://evolution-api:8080';
const EVO_KEY = 'SUBSTITUA_PELA_EVOLUTION_API_KEY';
const INSTANCE = 'principal';
const CRM = 'http://lovet-crm:3000';
const WA_TOKEN = 'SUBSTITUA_PELO_WA_API_TOKEN';
const OLLAMA = 'http://host.docker.internal:11434';
const MODEL = 'llama3.1:8b';
const VISION_MODEL = 'moondream';
const H_JSON = { 'Content-Type': 'application/json' };
const H_CRM = { 'Content-Type': 'application/json', 'x-webhook-token': WA_TOKEN };
const H_EVO = { 'Content-Type': 'application/json', apikey: EVO_KEY };

const http = async (o) => this.helpers.httpRequest(o);
// String(e) em erro de rede vira "[object Object]" e esconde o motivo real.
// Isso aqui pega a mensagem de verdade de onde ela costuma estar.
const errText = (e) => {
  try {
    const extra = e?.response?.data ?? e?.cause?.response?.data ?? e?.response?.body;
    const base = e?.message ? String(e.message) : JSON.stringify(e, Object.getOwnPropertyNames(e));
    return extra ? `${base} | ${typeof extra === 'string' ? extra : JSON.stringify(extra)}` : base;
  } catch { return String(e); }
};

const body = $input.first().json.body ?? $input.first().json;
const data = body.data ?? {};
const key = data.key ?? {};

// Filtros de seguranca
if (body.event !== 'messages.upsert') return [];
if (key.fromMe) return [];
const remoteJid = String(key.remoteJid || '');
if (!remoteJid.endsWith('@s.whatsapp.net')) return []; // ignora grupos, status, broadcast, canais
const phone = remoteJid.replace(/@.*/, '');
if (WHITELIST.length && !WHITELIST.includes(phone)) return [];
const name = data.pushName || phone;

// Só o número do GESTOR tem bot (regra de negócio). A instância do
// gestor vem do CRM (/api/wa/config, editável em WhatsApp → Follow-up). Mensagem
// que chega por outro número (consultor) é registrada no CRM e o bot não responde.
const INSTANCIA_MSG = String(body.instance || INSTANCE);
let instanciaGestor = INSTANCE;
try { instanciaGestor = (await http({ method: 'GET', url: CRM + '/api/wa/config', headers: H_CRM })).instanciaGestor || INSTANCE; } catch (e) {}
const ehNumeroDoGestor = INSTANCIA_MSG === instanciaGestor;

// Texto, audio, imagem ou documento
let text = data.message?.conversation ?? data.message?.extendedTextMessage?.text ?? '';
let mediaType = 'text';
let visionNote = null; // descricao automatica de imagem/documento, vira contexto extra pra IA

const audio = data.message?.audioMessage;
const image = data.message?.imageMessage;
const doc = data.message?.documentMessage;

if (!text && audio) {
  mediaType = 'audio';
  try {
    const media = await http({ method: 'POST', url: EVOLUTION + '/chat/getBase64FromMediaMessage/' + INSTANCIA_MSG, headers: H_EVO, body: { message: data } });
    const b64 = media.base64 || media?.data?.base64;
    // A transcricao em si roda no CRM (/api/wa/transcribe), nao aqui: o Code
    // node do n8n roda num processo separado (Task Runner) e, ao mandar um
    // Buffer binario pro processo principal montar a requisicao HTTP, o
    // Buffer vira {type:"Buffer", data:[...]} no meio do caminho — o
    // multipart sai quebrado (um "campo" por byte de audio). Passando so o
    // base64 (texto, sobrevive a serializacao) e deixando o CRM (Node.js sem
    // essa restricao) montar o multipart de verdade.
    const trans = await http({
      method: 'POST',
      url: CRM + '/api/wa/transcribe',
      headers: H_CRM,
      body: { base64: b64, mimetype: media.mimetype || 'audio/ogg' },
      timeout: 120000,
    });
    if (!trans.ok) throw new Error(trans.error || 'transcricao falhou');
    text = String(trans.text || '').trim();
  } catch (e) {
    // Nao conseguiu transcrever: pede por escrito e encerra.
    if (ehNumeroDoGestor) await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCIA_MSG, headers: H_EVO, body: { number: phone, text: 'Oi! Recebi seu áudio, mas não consegui ouvir direito por aqui 😅 Pode me mandar por mensagem escrita?' } });
    return [{ json: { phone, error: 'audio_failed', detail: errText(e) } }];
  }
} else if (!text && (image || doc)) {
  // Imagem (receita medica, foto de armacao, etc.) ou documento (PDF).
  // O modelo de visao local descreve em ingles (e o que ele faz bem); a Vista
  // usa essa descricao como contexto extra e responde ao cliente em portugues.
  mediaType = image ? 'image' : 'document';
  try {
    const media = await http({ method: 'POST', url: EVOLUTION + '/chat/getBase64FromMediaMessage/' + INSTANCIA_MSG, headers: H_EVO, body: { message: data } });
    const b64 = media.base64 || media?.data?.base64;
    const vision = await http({ method: 'POST', url: OLLAMA + '/api/generate', headers: H_JSON, body: { model: VISION_MODEL, stream: false, prompt: 'Describe this image in detail, including any text or numbers visible in it (such as an eyeglass prescription).', images: [b64] } });
    visionNote = String(vision.response || '').trim();
    text = (image?.caption || doc?.caption || '').trim() || (mediaType === 'image' ? '[Cliente enviou uma foto]' : '[Cliente enviou um documento]');
  } catch (e) {
    if (ehNumeroDoGestor) await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCIA_MSG, headers: H_EVO, body: { number: phone, text: 'Oi! Recebi seu arquivo, mas não consegui abrir direito por aqui 😅 Pode me contar o que tem nele?' } });
    return [{ json: { phone, error: 'media_failed', detail: errText(e) } }];
  }
}
if (!text) return [];

// Registra a mensagem no CRM e pega o estado da conversa
const inbound = await http({ method: 'POST', url: CRM + '/api/wa/inbound', headers: H_CRM, body: { phone, name, text, mediaType, providerMessageId: key.id, instancia: INSTANCIA_MSG } });
const conversationId = inbound.conversationId;
if (!ehNumeroDoGestor) return [{ json: { phone, conversationId, bot: 'desligado — número de consultor, atendimento manual' } }];
let botStatus = inbound.botStatus;
const history = inbound.history || [];
const flowState = inbound.flowState || 'menu';
const sector = inbound.sector || null;

// Retomar atendimento automatico
const resume = /(atendimento autom|voltar ao rob|reativar (o )?bot|ativar (o )?rob|menu inicial)/i.test(text);
if (botStatus === 'human' && !resume) {
  return [{ json: { phone, conversationId, skipped: 'atendimento humano ativo' } }];
}
if (resume && botStatus === 'human') {
  // Confirma a retomada direto, sem passar pela IA: se a frase-gatilho
  // ("atendimento automatico") ou o resto da conversa fizer a IA marcar
  // wants_human=true de novo nessa mesma chamada, cai no handoff outra vez
  // e devolve a mesma mensagem — foi exatamente o loop que aconteceu.
  await http({ method: 'POST', url: CRM + '/api/wa/handoff', headers: H_CRM, body: { conversationId, mode: 'auto' } });
  const resumeReply = 'Oi de novo! 😊 Voltei a te atender por aqui. Me diga o que você precisa que eu te direciono.';
  const sentResume = await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCE, headers: H_EVO, body: { number: phone, text: resumeReply } });
  await http({ method: 'POST', url: CRM + '/api/wa/outbound', headers: H_CRM, body: { conversationId, text: resumeReply, providerMessageId: sentResume?.key?.id } });
  return [{ json: { phone, conversationId, reply: resumeReply, botStatus: 'auto', resumed: true } }];
}

// ─── Roteiro de setores ────────────────────────────────────────────────────
// O cliente escolhe o setor antes de a IA começar a atender. Sem isso a IA
// responderia tudo com a mesma voz, e o pedido de humano não saberia para
// qual equipe tocar o alerta.

// (a) Conversa nova: manda o menu e para por aqui.
if (flowState === 'menu') {
  const cat = await http({ method: 'GET', url: CRM + '/api/wa/sectors', headers: H_CRM });
  if (cat.count > 0) {
    const saudacao = 'Oi! Aqui é da Lovet Distribuidora 👋\n\n' + cat.menu;
    const sentMenu = await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCE, headers: H_EVO, body: { number: phone, text: saudacao } });
    await http({ method: 'POST', url: CRM + '/api/wa/outbound', headers: H_CRM, body: { conversationId, text: saudacao, providerMessageId: sentMenu?.key?.id } });
    // Só marca como enviado DEPOIS do envio dar certo (ver a rota).
    await http({ method: 'POST', url: CRM + '/api/wa/sector-menu-sent', headers: H_CRM, body: { conversationId } });
    return [{ json: { phone, conversationId, step: 'menu_enviado' } }];
  }
}

// (b) Menu já enviado: a resposta do cliente é a escolha do setor.
if (flowState === 'awaiting_sector') {
  const escolha = await http({ method: 'POST', url: CRM + '/api/wa/choose-sector', headers: H_CRM, body: { conversationId, answer: text } });
  if (!escolha.matched) {
    // Não insiste nem trava: remanda o menu, uma vez.
    const cat = await http({ method: 'GET', url: CRM + '/api/wa/sectors', headers: H_CRM });
    const msg = 'Só pra eu te direcionar certo — me diga o número da opção:\n\n' + cat.menu;
    const sentAgain = await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCE, headers: H_EVO, body: { number: phone, text: msg } });
    await http({ method: 'POST', url: CRM + '/api/wa/outbound', headers: H_CRM, body: { conversationId, text: msg, providerMessageId: sentAgain?.key?.id } });
    return [{ json: { phone, conversationId, step: 'menu_reenviado' } }];
  }
  const nome = escolha.sector?.name || 'atendimento';
  const conf = 'Perfeito, te encaminhei para *' + nome + '* ✅ Pode me contar o que você precisa?';
  const sentConf = await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCE, headers: H_EVO, body: { number: phone, text: conf } });
  await http({ method: 'POST', url: CRM + '/api/wa/outbound', headers: H_CRM, body: { conversationId, text: conf, providerMessageId: sentConf?.key?.id } });
  return [{ json: { phone, conversationId, step: 'setor_escolhido', setor: nome } }];
}

// Gera a resposta com o Ollama (JSON estruturado)
const personaSetor = sector && sector.aiPersona
  ? sector.aiPersona
  : 'Você atende a Lovet Distribuidora. Ajude com dúvidas sobre produtos, pedidos e entregas (e-CNPJ, e-CPF, SafeID em nuvem).';

const system = [
  'Você é a assistente virtual da Lovet Distribuidora, atendendo no WhatsApp.',
  sector ? ('Você está atendendo o setor: ' + sector.name + '.') : '',
  personaSetor,
  'Regras: no máximo 3 frases curtas por resposta. No máximo 1 emoji, e só quando fizer sentido. Trate a pessoa pelo nome assim que souber. Nunca invente preço fechado, prazo garantido nem informação que você não tem — nesse caso diga que um atendente confirma.',
  'wants_human: marque true SÓ quando a pessoa pedir EXPLICITAMENTE para falar com uma pessoa/atendente/humano (ex: "quero falar com um atendente", "tem alguém aí?", "me passa pra uma pessoa"), OU quando o assunto exigir acesso a dados que você não tem (valor em aberto, reembolso, contrato específico). Pergunta comum sobre o serviço NÃO é pedido de humano — responda normalmente e marque false. Na dúvida, false.',
  'Se marcar wants_human=true, escreva em `reply` apenas uma confirmação curta de que vai chamar alguém — sem prometer prazo.',
  'Responda SOMENTE com o JSON pedido.',
].filter(Boolean).join(' ');
const schema = { type: 'object', properties: { reply: { type: 'string' }, wants_human: { type: 'boolean' }, qualified: { type: 'boolean' }, city: { type: ['string', 'null'] }, bill: { type: ['string', 'null'] } }, required: ['reply', 'wants_human', 'qualified'] };
const messages = [{ role: 'system', content: system }];
for (const m of history) messages.push({ role: m.direction === 'in' ? 'user' : 'assistant', content: m.body });
if (visionNote) messages.push({ role: 'system', content: 'O cliente acabou de enviar uma imagem/documento. Descrição automática (em inglês) do que foi enviado: ' + visionNote });

let out;
try {
  const ai = await http({ method: 'POST', url: OLLAMA + '/api/chat', headers: H_JSON, body: { model: MODEL, stream: false, format: schema, options: { temperature: 0.65 }, messages } });
  out = JSON.parse(ai.message.content);
} catch (e) {
  out = { reply: 'Oi! Que bom te ver por aqui 😊 Aqui é da Lovet Distribuidora — me conta, o que você está procurando hoje?', wants_human: false, qualified: false };
}

let reply = String(out.reply || '').trim();
if (out.wants_human) {
  // Abre o pedido COM o setor: é o que faz o alerta tocar só para a equipe
  // certa, em vez de notificar o escritório inteiro.
  const pedido = await http({ method: 'POST', url: CRM + '/api/wa/request-human', headers: H_CRM, body: { conversationId, summary: text.slice(0, 180) } });
  const setorTxt = pedido?.sector ? (' do setor ' + pedido.sector) : '';
  reply = pedido?.availableAgents > 0
    ? ('Combinado! Já estou chamando um atendente' + setorTxt + ' pra falar com você por aqui 🙌')
    : ('Combinado! Vou registrar seu pedido para um atendente' + setorTxt + '. Assim que alguém liberar, te respondem por aqui 🙌');
  reply += ' (Se quiser voltar a falar comigo, é só escrever "atendimento automático".)';
}
if (!reply) reply = 'Pode me contar um pouco mais? 😊';

// Resposta sempre em texto, mesmo quando o cliente falou por audio ou mandou
// imagem — a Vista entende os dois, mas responde por escrito.
const sentText = await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCE, headers: H_EVO, body: { number: phone, text: reply } });
const providerMessageId = sentText?.key?.id;

// Registra a resposta e salva/atualiza o contato no CRM
await http({ method: 'POST', url: CRM + '/api/wa/outbound', headers: H_CRM, body: { conversationId, text: reply, providerMessageId } });
if (!out.wants_human) {
  await http({ method: 'POST', url: CRM + '/api/contacts', headers: H_CRM, body: { phone, name, city: out.city || null, bill: out.bill || null, qualified: !!out.qualified } });
}

return [{ json: { phone, conversationId, reply, botStatus, wants_human: !!out.wants_human, qualified: !!out.qualified, mediaType } }];
